<?php
defined('ABSPATH') || exit;

/** Student-owned occurrence activity. Server timestamps are the stopwatch authority. */
final class CAFCC_Study {
    const OUTCOMES=array('not_started','read','attempted','needs_revision','completed','solved_independently');
    public static function table($kind){if(!in_array($kind,array('personal','sessions','events','highlights','scenarios','links','bulk'),true))throw new InvalidArgumentException('Unknown study storage.');global $wpdb;return $wpdb->prefix.'cafcc_study_'.$kind;}
    public static function migrate(){
        global $wpdb;$common="id bigint(20) unsigned NOT NULL AUTO_INCREMENT,";
        $schemas=array(
            'personal'=>$common."user_id bigint(20) unsigned NOT NULL, question_id bigint(20) unsigned NOT NULL, occurrence_id bigint(20) unsigned NOT NULL,
                revision bigint(20) unsigned NOT NULL DEFAULT 1, outcome varchar(32) NOT NULL DEFAULT 'not_started', tags_json text NOT NULL, read_at datetime DEFAULT NULL, modified_at datetime NOT NULL,
                PRIMARY KEY  (id),
                UNIQUE KEY student_occurrence (user_id,occurrence_id),
                KEY student_question (user_id,question_id),
                KEY revision_queue (user_id,outcome)",
            'sessions'=>$common."user_id bigint(20) unsigned NOT NULL, question_id bigint(20) unsigned NOT NULL, occurrence_id bigint(20) unsigned NOT NULL, stable_id varchar(120) NOT NULL,
                attempt_number int(10) unsigned NOT NULL, version bigint(20) unsigned NOT NULL DEFAULT 1, status varchar(16) NOT NULL, pause_reason varchar(32) NOT NULL DEFAULT '', outcome varchar(32) NOT NULL DEFAULT 'attempted',
                started_at bigint(20) unsigned NOT NULL, ended_at bigint(20) unsigned DEFAULT NULL, last_tick bigint(20) unsigned NOT NULL, active_seconds bigint(20) unsigned NOT NULL DEFAULT 0, paused_seconds bigint(20) unsigned NOT NULL DEFAULT 0,
                PRIMARY KEY  (id),
                UNIQUE KEY student_attempt (user_id,occurrence_id,attempt_number),
                KEY active_session (user_id,occurrence_id,status),
                KEY recent_activity (user_id,started_at)",
            'events'=>$common."user_id bigint(20) unsigned NOT NULL, request_key varchar(80) NOT NULL, request_hash varchar(64) NOT NULL, response_json longtext NOT NULL, created_at datetime NOT NULL,
                PRIMARY KEY  (id),
                UNIQUE KEY idempotency (user_id,request_key)",
            'highlights'=>$common."user_id bigint(20) unsigned NOT NULL, question_id bigint(20) unsigned NOT NULL, occurrence_id bigint(20) unsigned NOT NULL, content_kind varchar(16) NOT NULL,
                body_sha256 varchar(64) NOT NULL, quote_text text NOT NULL, prefix_text text NOT NULL, suffix_text text NOT NULL, created_at datetime NOT NULL,
                PRIMARY KEY  (id),
                KEY student_occurrence (user_id,occurrence_id,content_kind),
                KEY student_question (user_id,question_id)",
            'scenarios'=>$common."scenario_key varchar(120) NOT NULL, source_hash varchar(64) NOT NULL, revision bigint(20) unsigned NOT NULL DEFAULT 1, body_html longtext NOT NULL, evidence_json longtext NOT NULL, updated_at datetime NOT NULL,
                PRIMARY KEY  (id),
                UNIQUE KEY source_scenario (source_hash,scenario_key)",
            'links'=>$common."question_id bigint(20) unsigned NOT NULL, occurrence_id bigint(20) unsigned NOT NULL, parent_stable_id varchar(120) NOT NULL DEFAULT '', scenario_id bigint(20) unsigned NOT NULL DEFAULT 0, scenario_revision bigint(20) unsigned NOT NULL DEFAULT 0, alternative varchar(16) NOT NULL DEFAULT '',
                PRIMARY KEY  (id),
                UNIQUE KEY occurrence_id (occurrence_id),
                KEY scenario_id (scenario_id),
                KEY question_id (question_id)",
            'bulk'=>$common."owner_id bigint(20) unsigned NOT NULL, job_key varchar(64) NOT NULL, action varchar(24) NOT NULL, phase varchar(16) NOT NULL, cursor_position int(10) unsigned NOT NULL DEFAULT 0, selection_json longtext NOT NULL, results_json longtext NOT NULL, modified_at datetime NOT NULL,
                PRIMARY KEY  (id),
                UNIQUE KEY job_key (job_key)"
        );
        foreach($schemas as $kind=>$schema){$t=self::table($kind);$sql=preg_replace('/,\s*(?=[a-z_]+ (?:bigint|varchar|text|longtext|datetime|int))/',",\n",$schema);dbDelta("CREATE TABLE $t ($sql) ENGINE=InnoDB ".$wpdb->get_charset_collate().';');if(!$wpdb->get_var("SHOW TABLES LIKE '$t'"))return CAFCC_Repository::error('Study migration incomplete; original records retained.',503);}
        $rt=CAFCC_Studio::table();$cols=$wpdb->get_col("SHOW COLUMNS FROM $rt");foreach(array('pilot_gate','manual_quality_pass') as $col)if(!in_array($col,$cols,true)&&false===$wpdb->query("ALTER TABLE $rt ADD COLUMN $col tinyint(1) NOT NULL DEFAULT 0"))return CAFCC_Repository::error('Pilot review gate migration incomplete.',503);if(false===$wpdb->query("UPDATE $rt SET pilot_gate=1 WHERE subject_code='FR' AND LOWER(REPLACE(REPLACE(exam_attempt,',',''),' ','')) IN ('january2026','jan2026') AND pilot_gate=0"))return CAFCC_Repository::error('Pilot visibility gate migration incomplete.',503);
        return true;
    }
    public static function eligible($qid,$oid){
        if(!CAFCC_Access::eligible()||!CAFCC_Practice::visible_question($qid))return false;
        foreach(CAFCC_Explorer::occurrences($qid) as $o)if((int)$o['id']===(int)$oid)return true;return false;
    }
    private static function prior_progress($qid){global $wpdb;$status=$wpdb->get_var($wpdb->prepare('SELECT status FROM '.CAFCC_DB::table('progress').' WHERE user_id=%d AND question_id=%d',get_current_user_id(),$qid));return in_array($status,self::OUTCOMES,true)?$status:'not_started';}
    private static function personal($qid,$oid,$lock=false){global $wpdb;$t=self::table('personal');$uid=get_current_user_id();if($lock)$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $t (user_id,question_id,occurrence_id,outcome,tags_json,modified_at) VALUES (%d,%d,%d,%s,'[]',%s)",$uid,$qid,$oid,self::prior_progress($qid),current_time('mysql',true)));return $wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d AND occurrence_id=%d".($lock?' FOR UPDATE':''),$uid,$oid),ARRAY_A);}
    public static function state($qid,$oid){
        if(!self::eligible($qid,$oid))return CAFCC_Repository::error('Eligible published occurrence not found.',404);global $wpdb;$t=self::table('sessions');$p=self::personal($qid,$oid);$s=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d AND occurrence_id=%d ORDER BY attempt_number DESC LIMIT 1",get_current_user_id(),$oid),ARRAY_A);
        $content=CAFCC_Studio::occurrence_content($qid,$oid,'question');return array('revision'=>(int)($p['revision']??0),'outcome'=>$p['outcome']??self::prior_progress($qid),'tags'=>json_decode($p['tags_json']??'[]',true),'read_at'=>$p['read_at']??null,'session'=>$s?self::clock($s):null,'question_hash'=>$content?hash('sha256',$content['body_html']):null,'server_time'=>time());
    }
    private static function sync_progress($qid,$outcome){if($outcome===null||$outcome==='read')return true;$mapped=$outcome==='solved_independently'?'completed':$outcome;return CAFCC_Repository::set_progress($qid,$mapped);}
    public static function clock($s){foreach(array('id','question_id','occurrence_id','attempt_number','version','started_at','ended_at','last_tick','active_seconds','paused_seconds') as $key)if(isset($s[$key]))$s[$key]=(int)$s[$key];$delta=max(0,time()-(int)$s['last_tick']);$s['display_active_seconds']=(int)$s['active_seconds']+($s['status']==='running'?$delta:0);$s['display_paused_seconds']=(int)$s['paused_seconds']+($s['status']==='paused'?$delta:0);unset($s['user_id']);return $s;}
    public static function save($qid,$input){
        if(!is_array($input)||array_diff(array_keys($input),array('occurrence_id','expected_revision','outcome','tags','mark_read')))return CAFCC_Repository::error('Unexpected private activity fields.');$oid=CAFCC_Repository::id($input['occurrence_id']??null);if(is_wp_error($oid)||!self::eligible($qid,$oid))return CAFCC_Repository::error('Published occurrence not found.',404);
        if(isset($input['outcome'])&&!in_array($input['outcome'],self::OUTCOMES,true))return CAFCC_Repository::error('Choose an explicit practice outcome. Time spent is not proof of a correct solution.');
        $tags=$input['tags']??null;if($tags!==null){if(!is_array($tags)||!array_is_list($tags)||count($tags)>12)return CAFCC_Repository::error('Use up to 12 private tags.');foreach($tags as &$tag){if(!is_string($tag)||!trim($tag)||strlen($tag)>60)return CAFCC_Repository::error('Private tags must be short text.');$tag=sanitize_text_field($tag);}unset($tag);$tags=array_values(array_unique($tags));}
        if(is_wp_error($e=CAFCC_Bank_DB::transactional()))return $e;return CAFCC_Academic::transaction(function()use($qid,$oid,$input,$tags){global $wpdb;$p=self::personal($qid,$oid,true);$expected=(int)($input['expected_revision']??-1);if($expected!==((int)$p['revision'])&&!($expected===0&&(int)$p['revision']===1&&$p['outcome']===self::prior_progress($qid)&&$p['tags_json']==='[]'&&!$p['read_at']))return CAFCC_Repository::error('Private activity changed. Reload before saving.',409);$v=array('revision'=>(int)$p['revision']+1,'modified_at'=>current_time('mysql',true));if(isset($input['outcome']))$v['outcome']=$input['outcome'];if($tags!==null)$v['tags_json']=wp_json_encode($tags);if(true===($input['mark_read']??false))$v['read_at']=$p['read_at']?:current_time('mysql',true);if(false===$wpdb->update(self::table('personal'),$v,array('id'=>$p['id'])))return CAFCC_Repository::error('Cannot save private activity.',500);$synced=self::sync_progress($qid,$input['outcome']??null);if(is_wp_error($synced))return $synced;return self::state($qid,$oid);});
    }
    public static function session($qid,$input){
        if(!is_array($input)||array_diff(array_keys($input),array('occurrence_id','action','session_id','expected_version','request_key','outcome')))return CAFCC_Repository::error('Unexpected timer fields.');$oid=CAFCC_Repository::id($input['occurrence_id']??null);$key=$input['request_key']??'';$action=$input['action']??'';
        if(is_wp_error($oid)||!self::eligible($qid,$oid))return CAFCC_Repository::error('Published occurrence not found.',404);if(!is_string($key)||!preg_match('/^[A-Za-z0-9_-]{16,80}$/D',$key)||!in_array($action,array('start','pause','resume','finish'),true))return CAFCC_Repository::error('Use a valid idempotency key and timer action.');$outcome=$input['outcome']??'attempted';if(!in_array($outcome,self::OUTCOMES,true))return CAFCC_Repository::error('Invalid explicit practice outcome.');
        if(is_wp_error($e=CAFCC_Bank_DB::transactional()))return $e;return CAFCC_Academic::transaction(function()use($qid,$oid,$input,$key,$action,$outcome){global $wpdb;$uid=get_current_user_id();$p=self::personal($qid,$oid,true);$events=self::table('events');$hash=hash('sha256',wp_json_encode(array($qid,$input)));$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM $events WHERE user_id=%d AND request_key=%s",$uid,$key),ARRAY_A);if($old)return hash_equals($old['request_hash'],$hash)?json_decode($old['response_json'],true):CAFCC_Repository::error('Idempotency key reused with different data.',409);
            $t=self::table('sessions');$now=time();$s=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d AND occurrence_id=%d AND status IN ('running','paused') ORDER BY id DESC LIMIT 1 FOR UPDATE",$uid,$oid),ARRAY_A);
            if($action==='start'&&!$s){$attempt=1+(int)$wpdb->get_var($wpdb->prepare("SELECT MAX(attempt_number) FROM $t WHERE user_id=%d AND occurrence_id=%d",$uid,$oid));$rt=CAFCC_Studio::table();$stable=$wpdb->get_var($wpdb->prepare("SELECT stable_id FROM $rt WHERE occurrence_id=%d LIMIT 1",$oid));$v=array('user_id'=>$uid,'question_id'=>$qid,'occurrence_id'=>$oid,'stable_id'=>$stable?:'V1-'.$qid,'attempt_number'=>$attempt,'version'=>1,'status'=>'running','outcome'=>'attempted','started_at'=>$now,'last_tick'=>$now,'active_seconds'=>0,'paused_seconds'=>0);if(false===$wpdb->insert($t,$v))return CAFCC_Repository::error('Cannot start session.',500);$s=array_merge($v,array('id'=>$wpdb->insert_id));}
            elseif($action!=='start'){
                if(!$s||(string)$s['id']!==(string)($input['session_id']??'')||(string)$s['version']!==(string)($input['expected_version']??''))return CAFCC_Repository::error('Session changed or belongs to another occurrence. Reload its current state.',409);
                if(($action==='pause'&&$s['status']!=='running')||($action==='resume'&&$s['status']!=='paused'))return CAFCC_Repository::error('Invalid stopwatch transition.',409);$delta=max(0,$now-(int)$s['last_tick']);$field=$s['status']==='running'?'active_seconds':'paused_seconds';$s[$field]=(int)$s[$field]+$delta;$s['last_tick']=$now;$s['version']=(int)$s['version']+1;$s['status']=$action==='finish'?'finished':($action==='pause'?'paused':'running');$s['pause_reason']=$action==='pause'?'student':'';if($action==='finish'){$s['ended_at']=$now;$s['outcome']=$outcome;if(false===$wpdb->update(self::table('personal'),array('outcome'=>$outcome,'revision'=>(int)$p['revision']+1,'modified_at'=>current_time('mysql',true)),array('id'=>$p['id'])))return CAFCC_Repository::error('Cannot save practice result.',500);}if(false===$wpdb->update($t,$s,array('id'=>$s['id'])))return CAFCC_Repository::error('Cannot save stopwatch session.',500);
            }
            if($action==='finish'){$sync=self::sync_progress($qid,$outcome);if(is_wp_error($sync))return $sync;}$response=array('session'=>self::clock($s),'server_time'=>$now);if(false===$wpdb->insert($events,array('user_id'=>$uid,'request_key'=>$key,'request_hash'=>$hash,'response_json'=>wp_json_encode($response),'created_at'=>current_time('mysql',true))))return CAFCC_Repository::error('Cannot save timer event.',500);return $response;
        });
    }
    public static function highlights($qid,$oid,$kind='question',$input=null){
        if(!in_array($kind,array('question','answer'),true)||!self::eligible($qid,$oid))return CAFCC_Repository::error('Published content not found.',404);$content=CAFCC_Studio::occurrence_content($qid,$oid,$kind);if(!$content)return CAFCC_Repository::error('Permitted content unavailable.',404);$body=$content['body_html'];$plain=html_entity_decode(wp_strip_all_tags($body),ENT_QUOTES|ENT_HTML5,'UTF-8');$hash=hash('sha256',$body);global $wpdb;$t=self::table('highlights');$uid=get_current_user_id();
        if($input!==null){if(!is_array($input)||array_diff(array_keys($input),array('occurrence_id','kind','body_sha256','quote','prefix','suffix','delete_id')))return CAFCC_Repository::error('Unexpected highlight fields.');if(isset($input['delete_id'])){$id=CAFCC_Repository::id($input['delete_id']);if(is_wp_error($id))return $id;$wpdb->delete($t,array('id'=>$id,'user_id'=>$uid,'occurrence_id'=>$oid,'content_kind'=>$kind));}
            else{foreach(array('quote'=>1500,'prefix'=>150,'suffix'=>150) as $k=>$limit)if(!isset($input[$k])||!is_string($input[$k])||strlen($input[$k])>$limit)return CAFCC_Repository::error('Invalid highlight anchor.');if(($input['body_sha256']??'')!==$hash)return CAFCC_Repository::error('Content changed. Reopen it before highlighting.',409);if(!self::anchor($plain,$input['quote'],$input['prefix'],$input['suffix']))return CAFCC_Repository::error('Highlight is missing or ambiguous in this exact content.',409);$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $t WHERE user_id=%d AND occurrence_id=%d AND content_kind=%s",$uid,$oid,$kind));if($count>=100)return CAFCC_Repository::error('Keep at most 100 highlights per content.');if(false===$wpdb->insert($t,array('user_id'=>$uid,'question_id'=>$qid,'occurrence_id'=>$oid,'content_kind'=>$kind,'body_sha256'=>$hash,'quote_text'=>$input['quote'],'prefix_text'=>$input['prefix'],'suffix_text'=>$input['suffix'],'created_at'=>current_time('mysql',true))))return CAFCC_Repository::error('Cannot save private highlight.',500);}}
        $rows=$wpdb->get_results($wpdb->prepare("SELECT id,body_sha256,quote_text,prefix_text,suffix_text FROM $t WHERE user_id=%d AND occurrence_id=%d AND content_kind=%s ORDER BY id LIMIT 100",$uid,$oid,$kind),ARRAY_A);foreach($rows as &$r)$r['anchor_status']=self::anchor($plain,$r['quote_text'],$r['prefix_text'],$r['suffix_text'])?($r['body_sha256']===$hash?'current':'remapped_exact'):'unresolved';return array('items'=>$rows,'body_sha256'=>$hash);
    }
    public static function anchor($plain,$quote,$prefix,$suffix){if($quote==='')return false;$needle=$prefix.$quote.$suffix;return substr_count($plain,$needle)===1;}
    public static function dashboard(){
        if(!CAFCC_Access::eligible())return CAFCC_Repository::error('Current entitlement required.',403);global $wpdb;$uid=get_current_user_id();$s=self::table('sessions');$p=self::table('personal');$n=CAFCC_Practice::table('notebook');$q=CAFCC_DB::table('questions');$progress=CAFCC_DB::table('progress');
        $totals=$wpdb->get_row($wpdb->prepare("SELECT COUNT(*) AS completed_sessions,COALESCE(SUM(active_seconds),0) AS active_seconds,COALESCE(AVG(active_seconds),0) AS average_completed_seconds FROM $s WHERE user_id=%d AND status='finished'",$uid),ARRAY_A);
        $today=current_datetime()->setTime(0,0)->getTimestamp();$totals['total_active_seconds']=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(active_seconds+CASE WHEN status='running' THEN GREATEST(0,%d-last_tick) ELSE 0 END),0) FROM $s WHERE user_id=%d",time(),$uid));$totals['practised_today']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT question_id) FROM $s WHERE user_id=%d AND started_at>=%d",$uid,$today));
        $totals['attempted']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $q q WHERE EXISTS(SELECT 1 FROM $p a WHERE a.question_id=q.id AND a.user_id=%d AND a.outcome IN ('attempted','needs_revision','completed','solved_independently')) OR EXISTS(SELECT 1 FROM $progress b WHERE b.question_id=q.id AND b.user_id=%d AND b.status<>'not_started')",$uid,$uid));
        $totals['solved_independently']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT question_id) FROM $p WHERE user_id=%d AND outcome='solved_independently'",$uid));$totals['needs_revision']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $q q WHERE EXISTS(SELECT 1 FROM $p a WHERE a.question_id=q.id AND a.user_id=%d AND a.outcome='needs_revision') OR EXISTS(SELECT 1 FROM $progress b WHERE b.question_id=q.id AND b.user_id=%d AND b.status='needs_revision')",$uid,$uid));$totals['bookmarks']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $n WHERE user_id=%d AND bookmarked=1",$uid));$totals['notes']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $n WHERE user_id=%d AND note_text<>''",$uid));
        $recent=$wpdb->get_results($wpdb->prepare("SELECT s.id,s.question_id,s.occurrence_id,s.stable_id,s.attempt_number,s.status,s.outcome,s.started_at,s.ended_at,s.active_seconds,q.title FROM $s s JOIN $q q ON q.id=s.question_id WHERE s.user_id=%d ORDER BY s.id DESC LIMIT 20",$uid),ARRAY_A);
        $tags=$wpdb->get_results($wpdb->prepare("SELECT p.question_id,p.occurrence_id,p.tags_json,p.outcome,q.title FROM $p p JOIN $q q ON q.id=p.question_id WHERE p.user_id=%d AND (p.tags_json<>'[]' OR p.outcome='needs_revision') ORDER BY p.modified_at DESC LIMIT 30",$uid),ARRAY_A);
        $qt=CAFCC_DB::table('question_tags');$tx=CAFCC_DB::table('taxonomy');$topics=$wpdb->get_results($wpdb->prepare("SELECT t.id,t.title,t.node_type,COUNT(DISTINCT s.question_id) AS questions_practised,SUM(s.active_seconds) AS active_seconds FROM $s s JOIN $qt a ON a.question_id=s.question_id JOIN $tx t ON t.id=a.node_id WHERE s.user_id=%d AND s.status='finished' AND t.node_type IN ('chapter','topic','subtopic') GROUP BY t.id,t.title,t.node_type ORDER BY active_seconds DESC LIMIT 30",$uid),ARRAY_A);
        return array('totals'=>$totals,'recent_sessions'=>$recent,'revision_queue'=>$tags,'topic_activity'=>$topics,'note'=>'Personal activity only. Multiple topic tags can describe the same session. Time is not evidence of correctness.');
    }
    public static function pause_withdrawn($qid){global $wpdb;$t=self::table('sessions');$now=time();return false!==$wpdb->query($wpdb->prepare("UPDATE $t SET active_seconds=active_seconds+GREATEST(0,%d-last_tick),last_tick=%d,version=version+1,status='paused',pause_reason='source_withdrawn' WHERE question_id=%d AND status='running'",$now,$now,$qid));}
    public static function assets(){wp_enqueue_style('cafcc-study',plugins_url('assets/study.css',CAFCC_FILE),array('cafcc-v2'),CAFCC_VERSION);wp_enqueue_script('cafcc-study',plugins_url('assets/study.js',CAFCC_FILE),array(),CAFCC_VERSION,true);wp_localize_script('cafcc-study','CAFCCStudy',array('url'=>rest_url('cafcc/v6/'),'library'=>rest_url('cafcc/v9/'),'nonce'=>wp_create_nonce('wp_rest')));}
    public static function coverage(){
        if(!CAFCC_Access::eligible())return CAFCC_Repository::error('Current entitlement required.',403);global $wpdb;$r=new WP_REST_Request('GET');$r->set_param('exam_attempt','January 2026');$f=CAFCC_Facets::filters($r);if(is_wp_error($f))return $f;list($from,$where,$args)=CAFCC_Facets::parts($f,get_current_user_id());$o=CAFCC_DB::table('occurrences');$d=CAFCC_DB::table('documents');$dm=CAFCC_DB::table('document_meta');$p=self::table('personal');$from.=" JOIN $o coverage_o ON coverage_o.question_id=q.id JOIN $d coverage_d ON coverage_d.id=coverage_o.document_id JOIN $dm coverage_m ON coverage_m.document_id=coverage_d.id LEFT JOIN $p coverage_p ON coverage_p.occurrence_id=coverage_o.id AND coverage_p.user_id=".(int)get_current_user_id();$where.=" AND coverage_d.exam_attempt='January 2026' AND coverage_d.verification_status='verified' AND ".CAFCC_Academic::published('coverage_o').' AND '.CAFCC_Academic::published('coverage_m').CAFCC_Studio::occurrence_guard('coverage_o');
        $groups=$wpdb->get_results($wpdb->prepare("SELECT s.code AS subject,coverage_d.source_type,coverage_m.mtp_series,COUNT(*) AS eligible_occurrences,SUM(COALESCE(coverage_p.outcome,p.status,'not_started') IN ('completed','solved_independently')) AS personally_completed $from WHERE $where GROUP BY s.code,coverage_d.source_type,coverage_m.mtp_series",$args),ARRAY_A);$slots=$wpdb->get_results($wpdb->prepare("SELECT s.code AS subject,coverage_o.question_number,coverage_o.subquestion_number,COUNT(*) AS eligible_occurrences $from WHERE $where AND coverage_d.source_type='exam' GROUP BY s.code,coverage_o.question_number,coverage_o.subquestion_number ORDER BY coverage_o.question_number,coverage_o.subquestion_number LIMIT 100",$args),ARRAY_A);return array('attempt'=>'January 2026','source_coverage'=>$groups,'exam_slots'=>$slots,'historical_trends_available'=>false,'note'=>'One-attempt approved coverage only. No repetition or multi-year trend is inferred.');
    }
    public static function settings_screen(){if(!CAFCC_Repository::admin_allowed())wp_die('Administrator required.');$v=get_option('cafcc_study_help',array());echo '<div class="wrap"><h1>Study help and Quick Concepts</h1><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('cafcc_study_help','_wpnonce',true,false).'<input type="hidden" name="action" value="cafcc_study_help"><p><label>Owner tutorial / How It Works video URL <input type="url" name="tutorial_url" size="80" value="'.esc_attr($v['tutorial_url']??'').'"></label></p><p><label>Original or appropriately licensed editorial Quick Concepts (safe HTML)<br><textarea name="concepts_html" rows="12" cols="90">'.esc_textarea($v['concepts_html']??'').'</textarea></label></p><label><input type="checkbox" name="reviewed" value="1"> I approve this exact editorial text and its publication rights.</label><p><button class="button button-primary">Save help settings</button></p></form><p>AI explanations are not connected or enabled. No provider credentials, background requests or costs are introduced.</p></div>';}
    public static function init(){
        add_action('admin_menu',function(){if(CAFCC_Repository::admin_allowed())add_submenu_page('cafcc','Study help and Quick Concepts','Study help','manage_options','cafcc-study-help',array(__CLASS__,'settings_screen'));});
        add_action('admin_post_cafcc_study_help',function(){if(!CAFCC_Repository::admin_allowed()||!isset($_POST['_wpnonce'])||!is_string($_POST['_wpnonce'])||!wp_verify_nonce(wp_unslash($_POST['_wpnonce']),'cafcc_study_help'))wp_die('Secure administrator request required.','',array('response'=>403));$url=isset($_POST['tutorial_url'])&&is_string($_POST['tutorial_url'])?esc_url_raw(wp_unslash($_POST['tutorial_url'])):'';$html=isset($_POST['concepts_html'])&&is_string($_POST['concepts_html'])?wp_unslash($_POST['concepts_html']):'';if(($url&&(parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)||parse_url($url,PHP_URL_PASS)||CAFCC_Bank_DB::private_reference($url)))||strlen($url)>2048||strlen($html)>100000||CAFCC_Bank_DB::private_reference($html))wp_die('Use a public HTTPS tutorial and bounded original/licensed editorial notes.');$old=get_option('cafcc_study_help',array());$v=array('tutorial_url'=>$url,'concepts_html'=>CAFCC_Practice::html($html),'reviewed'=>isset($_POST['reviewed']),'reviewer_id'=>get_current_user_id(),'updated_at'=>current_time('mysql',true));update_option('cafcc_study_help',$v,false);CAFCC_Bank_DB::audit_master('study_help',0,$old,$v);wp_safe_redirect(admin_url('admin.php?page=cafcc-study-help'));exit;});
        add_action('rest_api_init',function(){$permission=function($r){return CAFCC_REST::permission($r);};
            register_rest_route('cafcc/v6','/dashboard',array('methods'=>'GET','permission_callback'=>$permission,'callback'=>array(__CLASS__,'dashboard')));
            register_rest_route('cafcc/v6','/coverage',array('methods'=>'GET','permission_callback'=>$permission,'callback'=>array(__CLASS__,'coverage')));
            register_rest_route('cafcc/v6','/study/(?P<id>[1-9][0-9]{0,17})',array(array('methods'=>'GET','permission_callback'=>$permission,'callback'=>function($r){return self::state((int)$r['id'],(int)$r->get_param('occurrence_id'));}),array('methods'=>'PUT','permission_callback'=>$permission,'callback'=>function($r){$d=CAFCC_Studio::body($r,16000);return is_wp_error($d)?$d:self::save((int)$r['id'],$d);})));
            register_rest_route('cafcc/v6','/study/(?P<id>[1-9][0-9]{0,17})/sessions',array('methods'=>'POST','permission_callback'=>$permission,'callback'=>function($r){$d=CAFCC_Studio::body($r,4000);return is_wp_error($d)?$d:self::session((int)$r['id'],$d);}));
            register_rest_route('cafcc/v6','/study/(?P<id>[1-9][0-9]{0,17})/highlights',array('methods'=>array('GET','POST'),'permission_callback'=>$permission,'callback'=>function($r){$d=$r->get_method()==='GET'?null:CAFCC_Studio::body($r,6000);if(is_wp_error($d))return $d;$oid=(int)($d['occurrence_id']??$r->get_param('occurrence_id'));$kind=$d['kind']??$r->get_param('kind')??'question';return self::highlights((int)$r['id'],$oid,$kind,$d);}));
        });
        add_filter('rest_post_dispatch',function($response,$server,$request){if(str_starts_with($request->get_route(),'/cafcc/v6/')){$response->header('Cache-Control','private, no-store');$response->header('Vary','Cookie');}return $response;},10,3);
    }
}
